import type {Metadata} from 'next';
import {ScenicImage,WhyUs,Adventure} from '@/components/sections';
import {Reveal} from '@/components/ui';
export const metadata:Metadata={title:'About Us'};
export default function About(){return <><section className="page-banner"><ScenicImage imageKey="hero" priority/><div className="banner-shade"/><div className="wrap"><span className="eyebrow light">MEET HIMALAYAHIKES</span><h1>For the journey.<br/>And everything it brings.</h1><p>Mountains at heart. Adventure in our soul.</p></div></section><section className="section"><div className="wrap about-story"><Reveal className="about-photo"><ScenicImage imageKey="jibhi"/></Reveal><Reveal><span className="eyebrow">BEYOND THE EVERYDAY</span><h2>Some places change<br/>the way you feel.</h2><p className="large-copy">A quiet valley. A trail that opens to a mountain view. A sunset that makes you put your phone away.</p><p>That's the spirit behind HimalayaHikes. We help you explore Himalayan destinations, trekking trails, and Rajasthan escapes, with trip planning that starts by listening to you.</p><p>Whether you're drawn to the riverside pace of Kasol, the landscapes of Hampta Pass, or the golden light of Jaisalmer, we're here to help you take the next step.</p><span className="story-signature">Go beyond the ordinary.</span></Reveal></div></section><WhyUs/><Adventure/></>}

import type {Metadata} from 'next';
import {ArrowUpRight,Compass} from 'lucide-react';
import {EnquiryForm} from '@/components/enquiry-form';
import {ScenicImage} from '@/components/sections';
import {WhatsAppIcon} from '@/components/ui';
import {whatsappUrl} from '@/lib/packages';
export const metadata:Metadata={title:'Contact Us'};
export default function Contact(){return <><section className="page-banner contact-banner"><ScenicImage imageKey="harshil" priority/><div className="banner-shade"/><div className="wrap"><span className="eyebrow light">EVERY ADVENTURE STARTS WITH HELLO</span><h1>Where do you<br/>want to go?</h1><p>Big plans or a little spark of an idea. We're listening.</p></div></section><section className="section"><div className="wrap contact-grid"><div><span className="eyebrow">LET'S TALK TRAVEL</span><h2>A message away<br/>from your next escape.</h2><p className="large-copy">Have a question about a destination? Need help choosing a trip? Start a conversation with HimalayaHikes.</p><a className="contact-method" href={whatsappUrl()} target="_blank" rel="noopener noreferrer"><span className="icon-tile"><WhatsAppIcon/></span><span><small>WHATSAPP US</small><strong>+91 85955 10125</strong></span><ArrowUpRight size={22}/></a><div className="contact-tip"><Compass size={24}/><p>Share your preferred destination, dates, and group size. We'll help you explore the possibilities.</p></div></div><EnquiryForm/></div></section></>}

