import Link from 'next/link';
import Image from 'next/image';
import {notFound} from 'next/navigation';
import {ArrowLeft,Check,MapPin,ArrowRight,Compass} from 'lucide-react';
import {packages} from '@/lib/packages';
import {photo,photos} from '@/lib/photos';
import {ScenicImage,PackageCard,Adventure} from '@/components/sections';
import {Reveal,WhatsAppButton} from '@/components/ui';
export function generateStaticParams(){return packages.map(p=>({slug:p.slug}))}
export const dynamicParams=false;
export async function generateMetadata({params}:{params:Promise<{slug:string}>}){const {slug}=await params;const p=packages.find(p=>p.slug===slug);return {title:p?.name||'Package',description:p?.tagline}}
export default async function PackageDetails({params}:{params:Promise<{slug:string}>}){const {slug}=await params;const p=packages.find(p=>p.slug===slug);if(!p)notFound();return <><section className="detail-banner"><ScenicImage imageKey={p.imageKey} priority/><div className="banner-shade"/><div className="wrap"><Link href="/packages/" className="back-link"><ArrowLeft size={16}/> All Packages</Link><span className="eyebrow light">{p.category}</span><h1>{p.name}</h1><p><MapPin size={17}/>{p.region}</p></div></section><div className="wrap detail-layout"><article><Reveal className="detail-intro"><span className="eyebrow">YOUR NEXT CHAPTER</span><h2>{p.tagline}</h2><p className="large-copy">{p.overview}</p></Reveal><section className="detail-section"><span className="eyebrow">THE THINGS YOU'LL REMEMBER</span><h2>Trip highlights</h2><p className="muted">A preview of what awaits. We'll customize every experience in your personalized plan.</p><ul className="highlights">{p.highlights.map(h=><li key={h}><span><Check size={17}/></span>{h}</li>)}</ul></section><section className="detail-section"><span className="eyebrow">A CLOSER LOOK</span><h2>Picture yourself here.</h2><div className="detail-gallery">{photos[p.imageKey].map((img,i)=><a key={img.src} href={img.src} target="_blank" rel="noopener noreferrer" aria-label={`Open ${img.alt}`} className={i===0?'gallery-wide':''}><Image src={img.src} alt={img.alt} fill sizes="(max-width: 640px) 100vw, 60vw" className="scenic-image"/></a>)}</div></section><section className="planning-note"><Compass size={30}/><div><h3>A journey planned around you.</h3><p>Message us for the itinerary, trip length, current pricing, and available dates for {p.name}. We'll share all inclusions, exclusions, and arrangements before you book.</p><WhatsAppButton destination={p.name}>Request Trip Details</WhatsAppButton></div></section></article><aside className="booking-sidebar"><span className="eyebrow">LET'S MAKE IT HAPPEN</span><h3>The mountains can wait.<br/>Your plans don't have to.</h3><p>Share your preferred dates, group size, and travel style. Let's start planning your {p.name} adventure.</p><WhatsAppButton destination={p.name}/><div className="sidebar-line"/><span className="location"><MapPin size={16}/>{p.region}</span><p className="sidebar-small">A simple conversation.<br/>A thoughtfully planned escape.</p></aside></div><section className="section related"><div className="wrap"><div className="section-heading heading-row"><div><span className="eyebrow">KEEP EXPLORING</span><h2>More places to fall in love with.</h2></div><Link className="text-link" href="/packages/">All Packages <ArrowRight size={18}/></Link></div><div className="package-grid">{packages.filter(x=>x.slug!==p.slug).sort((a,b)=>Number(b.category===p.category)-Number(a.category===p.category)).slice(0,3).map(x=><PackageCard item={x} key={x.slug}/>)}</div></div></section><Adventure/></>}

