export default function Home(){const gallery=[{key:'hampta',label:'Take the scenic route',sub:'HAMPTA PASS'},{key:'udaipur',label:'Chase the golden hour',sub:'UDAIPUR'},{key:'jibhi',label:'Find a little stillness',sub:'JIBHI & TIRTHAN'},{key:'jaisalmer',label:'Beyond the mountains',sub:'JAISALMER'},{key:'chopta',label:'A higher perspective',sub:'CHOPTA & TUNGNATH'}];return <>
 <section className="hero"><ScenicImage imageKey="hero" priority/><div className="hero-shade"/><div className="wrap hero-content"><Reveal><span className="hero-kicker"><span/> THE MOUNTAINS ARE CALLING</span><h1>Discover the Beauty<br/>of the <em>Himalayas</em></h1><p>Explore breathtaking destinations, unforgettable treks, and<br className="desktop-only"/> extraordinary adventures with HimalayaHikes.</p><div className="hero-buttons"><Link className="button button-orange" href="/packages/">Explore Packages <ArrowUpRightIcon/></Link><WhatsAppButton className="button-glass"/></div></Reveal><div className="hero-bottom"><span><MapPin size={15}/> Somewhere you'd rather be.</span><a href="#destinations">SCROLL TO EXPLORE <ArrowDown size={16}/></a><span className="hero-coordinate">A LITTLE WILDER. A LITTLE FREER.</span></div></div><div className="hero-side">FIND YOUR NEXT CHAPTER</div></section>
 <div className="journey-strip"><div className="wrap"><span><Mountain size={20}/> Mountains & beyond</span><i/><span><Compass size={20}/> Handcrafted experiences</span><i/><span><MapPin size={20}/> 9 extraordinary destinations</span></div></div>
 <section id="destinations" className="section destinations-section"><div className="wrap"><Reveal className="section-heading heading-row"><div><span className="eyebrow">PICK A PLACE. MAKE A MEMORY.</span><h2>Explore Our Destinations<span className="orange-dot">.</span></h2><p>From misty mountain trails to golden desert skies,<br/>your next adventure is waiting.</p></div><Link className="text-link" href="/packages/">View All Packages <ArrowRight size={18}/></Link></Reveal><div className="package-grid">{packages.map(p=><PackageCard key={p.slug} item={p}/>)}</div></div></section>
 <WhyUs/>
 <section className="section gallery-section"><div className="wrap"><Reveal className="section-heading heading-row"><div><span className="eyebrow">MOMENTS THAT MAKE THE JOURNEY</span><h2>A world worth stepping into<span className="orange-dot">.</span></h2></div><p>Inspiration for<br/>your next journey.</p></Reveal><div className="masonry">{gallery.map((g,i)=>{const p=photo(g.key,1);const destination=packages.find(p=>p.imageKey===g.key)!;return <Link className={`gallery-tile gallery-${i}`} key={g.key} href={`/packages/${destination.slug}/`}><Image src={p.src} alt={p.alt} fill sizes="(max-width: 640px) 100vw, 50vw" className="scenic-image"/><span><small>{g.sub}</small><strong>{g.label}</strong></span><ArrowRight size={22}/></Link>})}</div></div></section><Adventure/>
 </>}
