export function EnquiryForm(){const [name,setName]=useState('');const [destination,setDestination]=useState('');const [message,setMessage]=useState('');return <form className="enquiry-form" action={`https://wa.me/${whatsappNumber}`} target="_blank" rel="noopener noreferrer" method="get"><h2>Let's plan something wonderful.</h2><p>Tell us a little about your travel plans.</p><label>Your name<input value={name} onChange={e=>setName(e.target.value)} placeholder="What should we call you?" autoComplete="name" required maxLength={100}/></label><label>Your destination<select value={destination} onChange={e=>setDestination(e.target.value)} required><option value="">Where would you like to go?</option>{packages.map(p=><option key={p.slug} value={p.name}>{p.name}</option>)}</select></label><label>Your travel ideas <span>(optional)</span><textarea value={message} onChange={e=>setMessage(e.target.value)} placeholder="Preferred dates, group size, or anything you have in mind..." rows={4} maxLength={2000}/></label><input type="hidden" name="text" value={`Hello HimalayaHikes, I'm ${name}. I want details about ${destination}.${message?` ${message}`:''}`}/><button type="submit" className="button button-orange"><WhatsAppIcon/>Continue on WhatsApp <ArrowUpRight size={18}/></button><small>This opens WhatsApp with your message ready to send.</small></form>}

'use client';
import {useState} from 'react';
import {Search, ArrowRight} from 'lucide-react';
