const filters=['All Destinations','Mountain Escapes','Treks & Trails','Royal Rajasthan'];
export function PackageExplorer(){const [filter,setFilter]=useState(filters[0]);const [query,setQuery]=useState('');const results=packages.filter(p=>(filter===filters[0]||p.category===filter)&&`${p.name} ${p.region}`.toLowerCase().includes(query.toLowerCase()));return <><div className="explorer-controls"><div className="filters" aria-label="Filter packages">{filters.map(f=><button key={f} aria-pressed={f===filter} onClick={()=>setFilter(f)} className={f===filter?'selected':''}>{f}</button>)}</div><label className="search"><Search size={17}/><input aria-label="Search destinations" placeholder="Find your destination" value={query} onChange={e=>setQuery(e.target.value)}/></label></div><p className="result-count" aria-live="polite">{results.length} destinations to discover</p><div className="package-grid">{results.map(p=><PackageCard key={p.slug} item={p}/>)}</div>{!results.length&&<div className="empty-results"><h3>A different adventure awaits.</h3><p>Try another destination or explore all our escapes.</p><button className="button button-orange" onClick={()=>{setFilter(filters[0]);setQuery('')}}>Show All Destinations <ArrowRight size={18}/></button></div>}</>}

