export function ScenicImage({imageKey,index=0,priority=false,className=''}:{imageKey:string;index?:number;priority?:boolean;className?:string}) { const p=photo(imageKey,index);return <picture><source media="(max-width: 640px)" srcSet={p.small}/><Image src={p.src} alt={p.alt} fill priority={priority} sizes="100vw" className={`scenic-image ${className}`}/></picture>; }
export function PackageCard({item}:{item:Package}) { const p=photo(item.imageKey);return <Reveal className="package-card"><Link href={`/packages/${item.slug}/`} className="card-photo" aria-label={`View ${item.name} package`}><Image src={p.small} alt={p.alt} fill sizes="(max-width: 640px) 100vw, (max-width: 1000px) 50vw, 33vw" className="scenic-image"/><span className="card-badge">{item.category}</span><span className="photo-arrow"><ArrowUpRight size={20}/></span></Link><div className="card-content"><span className="location"><MapPin size={13}/>{item.region}</span><Link href={`/packages/${item.slug}/`}><h3>{item.name}</h3></Link><p>{item.tagline}</p><div className="card-actions"><Link href={`/packages/${item.slug}/`}>View Package <ArrowRight size={15}/></Link><a href={whatsappUrl(item.name)} aria-label={`WhatsApp enquiry about ${item.name}`} target="_blank" rel="noopener noreferrer"><WhatsAppIcon/> <span>WhatsApp Enquiry</span></a></div></div></Reveal>; }
export function WhyUs(){const items=[{Icon:Mountain,title:'Beautiful Destinations',text:'From iconic peaks to serene valleys, find a place that speaks to you.'},{Icon:Compass,title:'Memorable Adventures',text:'Make room for new trails, authentic discoveries, and moments that stay with you.'},{Icon:Route,title:'Personalized Trip Planning',text:'Share your travel vision. We\'ll help shape a journey around you.'},{Icon:MessageCircle,title:'Easy WhatsApp Enquiries',text:'A real conversation is all it takes to start planning your escape.'}];return <section className="why-section section"><div className="wrap"><Reveal className="section-heading centered"><span className="eyebrow">THE HIMALAYAHIKES WAY</span><h2>A little more than a holiday.</h2><p>Good places. Thoughtful plans. A journey crafted around you.</p></Reveal><div className="why-grid">{items.map(({Icon,title,text},i)=><Reveal className="why-card" key={title}><span className="why-number">0{i+1}</span><span className="icon-tile"><Icon size={27} strokeWidth={1.4}/></span><h3>{title}</h3><p>{text}</p></Reveal>)}</div></div></section>}
export function Adventure(){return <section className="adventure"><ScenicImage imageKey="hero"/><div className="adventure-shade"/><Reveal className="adventure-content"><span className="eyebrow light">LESS SCROLLING. MORE EXPLORING.</span><h2>Your Next Adventure<br/>Starts Here</h2><p>Tell us where you dream of going.<br className="mobile-only"/> Let's plan your perfect escape.</p><WhatsAppButton>Plan My Adventure</WhatsAppButton></Reveal></section>}
export function Footer(){return <footer><div className="wrap footer-grid"><div className="footer-brand"><Link href="/"><Brand/></Link><p>For the love of mountains,<br/>and every trail beyond.</p><span className="footer-note">Your next story starts with an adventure.</span></div><div><h3>Explore</h3><Link href="/">Home</Link><Link href="/packages/">All Packages</Link><Link href="/about/">About Us</Link><Link href="/contact/">Contact Us</Link></div><div className="footer-destinations"><h3>Find Your Escape</h3>{packages.map(p=><Link key={p.slug} href={`/packages/${p.slug}/`}>{p.name}</Link>)}</div><div><h3>Let's Talk Travel</h3><p>Have a destination in mind?<br/>We're a message away.</p><a className="footer-contact" href={whatsappUrl()} target="_blank" rel="noopener noreferrer"><WhatsAppIcon/>+91 85955 10125</a><a href={whatsappUrl()} target="_blank" rel="noopener noreferrer">Chat with us on WhatsApp <ArrowUpRight size={15}/></a></div></div><div className="wrap footer-bottom"><span>&copy; {new Date().getFullYear()} HimalayaHikes. All rights reserved.</span><Link href="/photo-credits/">Photography credits</Link><span>Crafted for the wandering soul.</span></div></footer>}

'use client';
import { motion, useReducedMotion } from 'motion/react';
import { useState, useEffect, useRef } from 'react';
import Link from 'next/link';
import Image from 'next/image';
import { ArrowUpRight, Menu, X } from 'lucide-react';
import { usePathname } from 'next/navigation';
import { whatsappUrl } from '@/lib/packages';

export function WhatsAppIcon({className = ''}: {className?: string}) { return <svg className={className} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.65" aria-hidden="true"><path d="M20.3 11.7a8.3 8.3 0 0 1-12.4 7.2L3 20.3l1.4-4.8a8.3 8.3 0 1 1 15.9-3.8Z"/><path d="m8.2 7.3 1.5 2.4-.9 1.1c.8 1.8 1.9 2.9 3.8 3.7l1.1-1 2.5 1.4c.2 1.7-1.1 2.5-2.7 2-3.7-1.1-6.3-3.7-7.3-6.6-.5-1.6.4-3 2-3Z"/></svg>; }
export function Reveal({children, className = ''}: {children: React.ReactNode; className?: string}) { const reduced = useReducedMotion(); return <motion.div className={className} initial={false} whileInView={reduced ? undefined : {opacity:[0.65,1], y:[20,0]}} viewport={{once:true,amount:0.08}} transition={{duration:0.65}}>{children}</motion.div>; }
export function Brand() { return <span className="brand"><Image src="/himalayahikes-logo.png" alt="HimalayaHikes mountain sunrise logo" width={2121} height={709} className="brand-logo" priority/></span>; }
export function Header() {
 const [open,setOpen]=useState(false); const pathname=usePathname(); const menuRef=useRef<HTMLButtonElement>(null);
 useEffect(()=>{setOpen(false)},[pathname]);
 useEffect(()=>{if(!open)return;const key=(e:KeyboardEvent)=>{if(e.key==='Escape'){setOpen(false);menuRef.current?.focus()}};document.addEventListener('keydown',key);return()=>document.removeEventListener('keydown',key)},[open]);
 const links=[['/','Home'],['/packages/','All Packages'],['/about/','About Us'],['/contact/','Contact Us']];
 return <header className="site-header"><div className="nav-inner"><Link href="/" aria-label="HimalayaHikes home"><Brand/></Link><nav aria-label="Main navigation" className="desktop-nav">{links.map(([href,label])=><Link key={href} href={href} className={(href==='/'?pathname==='/':pathname.startsWith(href.slice(0,-1)))?'active':''}>{label}</Link>)}</nav><a className="button button-orange header-cta" href={whatsappUrl()} target="_blank" rel="noopener noreferrer">Plan a Trip <ArrowUpRight size={17}/></a><button ref={menuRef} className="menu-button" aria-label={open?'Close menu':'Open menu'} aria-expanded={open} aria-controls="mobile-nav" onClick={()=>setOpen(!open)}>{open?<X/>:<Menu/>}</button></div>{open&&<nav id="mobile-nav" className="mobile-nav" aria-label="Mobile navigation">{links.map(([href,label])=><Link href={href} key={href}>{label}</Link>)}<a href={whatsappUrl()} target="_blank" rel="noopener noreferrer">Plan on WhatsApp <ArrowUpRight size={18}/></a></nav>}</header>;
}
export function WhatsAppButton({destination,children='Book on WhatsApp',className=''}:{destination?:string;children?:React.ReactNode;className?:string}) { return <a className={`button button-orange ${className}`} href={whatsappUrl(destination)} target="_blank" rel="noopener noreferrer"><WhatsAppIcon/>{children}<ArrowUpRight size={17}/></a>; }
export function FloatingWhatsApp(){return <a className="floating-whatsapp" href={whatsappUrl()} aria-label="Chat with HimalayaHikes on WhatsApp" target="_blank" rel="noopener noreferrer"><WhatsAppIcon/></a>}

export type Package = { slug: string; name: string; region: string; category: 'Mountain Escapes' | 'Treks & Trails' | 'Royal Rajasthan'; imageKey: string; tagline: string; overview: string; highlights: string[] };
export const packages: Package[] = [
 {slug:'manali-kasol',name:'Manali - Kasol',region:'Himachal Pradesh',category:'Mountain Escapes',imageKey:'manali',tagline:'Pine-scented air. Riverside days. Mountain magic.',overview:'From the mountain-town charm of Manali to the riverside tranquility of Kasol, experience the vibrant contrast of Himachal Pradesh. Discover forested slopes, panoramic Himalayan vistas, and peaceful valley moments.',highlights:['Mountain landscapes around Manali','Riverside atmosphere and cafes of Kasol','Pine forests and scenic valley trails','Authentic Himachali culture and local life']},
 {slug:'chopta-tungnath',name:'Chopta - Tungnath',region:'Uttarakhand',category:'Treks & Trails',imageKey:'chopta',tagline:'Follow the trail to a higher kind of happiness.',overview:'Chopta\'s alpine meadows and lush forests lead towards the ancient mountain shrine of Tungnath and Chandrashila peak. This Garhwal escape pairs gentle trails with sweeping Himalayan panoramas.',highlights:['Lush alpine meadows of Chopta','Scenic trail towards Tungnath and Chandrashila','Garhwal Himalayan panoramas','Forest walks and alpine photography']},
 {slug:'udaipur-mount-abu-kumbhalgarh',name:'Udaipur - Mount Abu / Kumbhalgarh',region:'Rajasthan',category:'Royal Rajasthan',imageKey:'udaipur',tagline:'Lakeside sunsets and stories written in stone.',overview:'Journey through the regal heritage of Rajasthan: from the romantic lakes and palaces of Udaipur to the serene hill trails of Mount Abu and the monumental ramparts of Kumbhalgarh Fort.',highlights:['Udaipur\'s iconic lakes and palace views','Cool breezes and hill scenery of Mount Abu','Historic ramparts of Kumbhalgarh Fort','Vibrant Rajasthani arts, architecture, and heritage']},
 {slug:'chakrata',name:'Chakrata',region:'Uttarakhand',category:'Mountain Escapes',imageKey:'chakrata',tagline:'A quieter corner of the mountains.',overview:'Escape the crowds and immerse yourself in Chakrata\'s serene deodar-covered hills and panoramic views. This tranquil Uttarakhand retreat is tailor-made for unhurried nature walks and crisp mountain air.',highlights:['Dense deodar forests and scenic trails','Peaceful mountain walks away from busy hubs','Panoramic Himalayan viewpoints','Pristine landscapes of Jaunsar-Bawar']},
 {slug:'hampta-pass',name:'Hampta Pass',region:'Himachal Pradesh',category:'Treks & Trails',imageKey:'hampta',tagline:'One trail. A world of dramatic landscapes.',overview:'Hampta Pass offers an unforgettable crossover trek, bridging the lush green Kullu Valley with the stark, dramatic expanse of Lahaul. Traverse alpine meadows, cross mountain streams, and marvel at towering peaks.',highlights:['Dramatic crossover between Kullu and Lahaul','Alpine meadows, mountain streams, and wildflowers','Breathtaking high-altitude Himalayan terrain','An unforgettable crossover trekking experience']},
 {slug:'harshil-valley',name:'Harshil Valley',region:'Uttarakhand',category:'Mountain Escapes',imageKey:'harshil',tagline:'Where the river leads you to peace.',overview:'Nestled along the Bhagirathi River in Uttarakhand, Harshil Valley offers serene deodar forests, apple orchards, and traditional Himalayan villages - a peaceful retreat to pause, breathe, and unwind.',highlights:['Pristine Bhagirathi River scenery','Deodar forests and scenic valley trails','Traditional Himalayan villages and architecture','Peaceful, unhurried mountain moments']},
 {slug:'kasol-kheerganga',name:'Kasol - Kheerganga',region:'Himachal Pradesh',category:'Treks & Trails',imageKey:'kasol',tagline:'Riverside beginnings. Unforgettable trails.',overview:'Discover the natural charm of Parvati Valley in Kasol before embarking on the scenic mountain trail to Kheerganga. Follow rushing rivers through pine woodlands and soothing natural hot springs framed by majestic peaks.',highlights:['Enchanting landscapes of Parvati Valley','Riverside cafe and village culture of Kasol','Forested trails leading to Kheerganga','Natural hot springs and panoramic viewpoints']},
 {slug:'jaisalmer',name:'Jaisalmer',region:'Rajasthan',category:'Royal Rajasthan',imageKey:'jaisalmer',tagline:'Golden sands. Timeless stories.',overview:'Step into a world of golden sandstone architecture and open desert horizons. From the living fort and winding alleys of the Golden City to sunsets over the Thar Desert dunes, experience Rajasthan in pure wonder.',highlights:['Golden sandstone architecture and the historic fort','Atmospheric old-city alleys, havelis, and bazaars','Sunsets and open horizons of the Thar Desert','Authentic Rajasthani culture and desert hospitality']},
 {slug:'jibhi-tirthan-valley',name:'Jibhi - Tirthan',region:'Himachal Pradesh',category:'Mountain Escapes',imageKey:'jibhi',tagline:'Find your own peaceful corner of the Himalayas.',overview:'Wooded hillsides, traditional wooden architecture, and crystalline streams define Jibhi and the pristine Tirthan Valley. Embrace a slower travel rhythm surrounded by pine forests, waterfalls, and warm mountain hospitality.',highlights:['Charming wooded village setting of Jibhi','Crystal-clear rivers and waterfalls of Tirthan Valley','Traditional Himachali architecture and homestays','Unhurried nature walks and forest trails']},
];
export const whatsappNumber = '918595510125';
export function whatsappUrl(destination?: string) { return `https://wa.me/${whatsappNumber}?text=${encodeURIComponent(destination ? `Hello HimalayaHikes, I want details about ${destination}` : 'Hello HimalayaHikes, I would like to plan my next adventure.')}`; }

import credits from './photo-credits.json';
export type Photo = { src: string; small: string; alt: string; author: string; page: string; license: string; licenseUrl: string };
export const photos = credits as Record<string, Photo[]>;
export function photo(key: string, index = 0): Photo { return photos[key][index % photos[key].length]; }

